const cars=[{id:'solaris',name:'Hyundai Solaris',category:'economy',label:'Эконом',price:2500,gear:'Автомат',seats:5,image:'assets/hero.png'},{id:'k5',name:'Kia K5',category:'comfort',label:'Комфорт',price:4500,gear:'Автомат',seats:5,image:'assets/hero.png'},{id:'tucson',name:'Hyundai Tucson',category:'suv',label:'Кроссовер',price:5500,gear:'Автомат',seats:5,image:'assets/hero.png'}];
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('ru-RU').format(n), config=window.RENTAL_CONFIG||{};
let filter='all',selected=null,copyText='';
// Inputs are explicitly interpreted in the rental location's UTC+03:00 zone.
function period(){const start=$('#start').value,end=$('#end').value;const a=new Date(start+'+03:00'),b=new Date(end+'+03:00');if(!start||!end||!Number.isFinite(+a)||!Number.isFinite(+b))throw Error('Укажите даты и время получения и возврата.');if(a<=new Date())throw Error('Получение должно быть в будущем.');if(b<=a)throw Error('Возврат должен быть позже получения.');return {start:a.toISOString(),end:b.toISOString(),days:Math.ceil((b-a)/86400000)};}
function render(){ $('#cars').innerHTML=cars.filter(c=>filter==='all'||c.category===filter).map(c=>`<article class="car"><div class="image"><img src="${c.image}" alt="Иллюстрация путешествия по Кавказу; фото ${c.name} будет добавлено" loading="lazy"><span class="tag">${c.label}</span></div><div class="car-body"><h3>${c.name}</h3><div class="specs"><span>◉ ${c.gear}</span><span>♧ ${c.seats} мест</span><span>Кондиционер</span></div><div class="car-bottom"><div class="price">${money(c.price)} ₽ <small>/ сутки</small></div><button class="pick" data-car="${c.id}">Выбрать ↗</button></div></div></article>`).join('');document.querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>choose(b.dataset.car));}
function choose(id){let p;try{p=period();$('#date-error').textContent='';}catch(e){$('#date-error').textContent=e.message;$('.booking').scrollIntoView({behavior:'smooth'});$('#start').focus();return;}selected=cars.find(c=>c.id===id);$('#selected-name').textContent=selected.name;const fmt=s=>new Date(s).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',dateStyle:'short',timeStyle:'short'});copyText=`Предварительный расчет: ${selected.name}\nМинеральные Воды (МСК)\nПолучение: ${fmt(p.start)}\nВозврат: ${fmt(p.end)}\nСуток: ${p.days}\nСтоимость: ${money(p.days*selected.price)} ₽\nТребуется подтверждение менеджера.`;$('#summary').textContent=copyText;$('#summary').style.whiteSpace='pre-line';$('#copy-status').textContent='';$('#bot-link').hidden=true;$('#bot-status').textContent='Telegram-бот еще не подключен. Можно скопировать расчет; это не создает бронирование.';$('#booking-dialog').showModal();if(config.apiBase&&config.botUsername)createHandoff(p);}
async function createHandoff(p){try{const r=await fetch(config.apiBase.replace(/\/$/,'')+'/api/bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({car_id:selected.id,start:p.start,end:p.end})});if(!r.ok)throw Error();const data=await r.json();if(!/^[A-Za-z0-9_-]{10,64}$/.test(data.token)||!/^\w{5,32}$/.test(config.botUsername))throw Error();$('#bot-link').href=`https://t.me/${config.botUsername}?start=${data.token}`;$('#bot-link').hidden=false;$('#bot-status').textContent='Продолжите заявку в Telegram. Наличие автомобиля подтвердит менеджер.';}catch{$('#bot-status').textContent='Не удалось связаться с сервером. Попробуйте позже; заявка не подтверждена.';}}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render();});$('#find').onclick=()=>{try{period();$('#date-error').textContent='';$('#fleet').scrollIntoView({behavior:'smooth'});}catch(e){$('#date-error').textContent=e.message;}};$('.close').onclick=()=>$('#booking-dialog').close();$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(copyText);$('#copy-status').textContent='Расчет скопирован';}catch{$('#copy-status').textContent='Выделите расчет выше и скопируйте вручную.';}};
const now=new Date(),local=d=>new Date(+d+10800000).toISOString().slice(0,16);const start=new Date(+now+86400000);start.setUTCMinutes(0,0,0);$('#start').min=local(now);$('#start').value=local(start);$('#end').value=local(new Date(+start+3*86400000));render();
